1	"use client";
2	
3	import {
4	  createContext,
5	  useCallback,
6	  useContext,
7	  useEffect,
8	  useMemo,
9	  useRef,
10	  useState,
11	  type ReactNode,
12	} from "react";
13	import { useRouter } from "next/navigation";
14	import {
15	  getWorkspace,
16	  importWorkspace as apiImportWorkspace,
17	  syncWorkspace as apiSyncWorkspace,
18	  type ApiError,
19	  type ImportWorkspaceRequest,
20	  type LocalWorkspaceSummary,
21	  type WorkspaceDetail,
22	} from "@/services/workflow-backend";
23	import { buildImportLocalSummary } from "@/features/workspaces/lib/workspaceAdapter";
24	import {
25	  getLocalWorkspaceSummaries,
26	  getSelectedWorkspaceId,
27	  clearSelectedWorkspaceId,
28	  resolveBootstrapWorkspaceId,
29	  saveLocalWorkspaceSummary,
30	  removeLocalWorkspaceSummary,
31	  setSelectedWorkspaceId,
32	} from "@/services/local-workspace-store";
33	import {
34	  addTaskTab,
35	  removeTaskTab,
36	  addFeatureTab,
37	  removeFeatureTab,
38	  createTabSessionId,
39	  getTaskTabHref,
40	  getFeatureTabHref,
41	} from "@/features/workspaces/lib/tabState";
42	import { createRequestSequence } from "@/lib/request-sequence";
43	import {
44	  clearStatusFilter,
45	  clearFeatureStatusFilter,
46	  clearBoardMode,
47	} from "@/features/board/lib/status-filter-store";
48	import { useQueryClient } from "@tanstack/react-query";
49	import { workspaceKeys } from "@/lib/query-keys";
50	
51	export type TaskTabEntry = {
52	  sessionId: string;
53	  workspaceId: string;
54	  taskId: string;
55	  taskName: string;
56	  title: string;
57	  featureId?: string;
58	  featureName?: string;
59	  /** When set, closing this task tab should reactivate the parent feature tab. */
60	  parentFeatureTabSessionId?: string;
61	};
62	
63	export type FeatureTabEntry = {
64	  sessionId: string;
65	  workspaceId: string;
66	  featureId: string;
67	  featureName: string;
68	  title: string;
69	};
70	
71	export type WorkspaceSurface = "board" | "task-tab" | "feature-tab";
72	
73	export type TabOpenOptions = {
74	  forceNewSession?: boolean;
75	};
76	
77	export type WorkspaceContextValue = {
78	  summaries: LocalWorkspaceSummary[];
79	  selectedWorkspaceId: string | null;
80	  activeWorkspace: WorkspaceDetail | null;
81	  loadingWorkspace: boolean;
82	  workspaceError: ApiError | null;
83	  importingWorkspace: boolean;
84	  importError: ApiError | null;
85	  syncingWorkspace: boolean;
86	  syncError: ApiError | null;
87	
88	  selectWorkspace: (workspaceId: string) => void;
89	  importWorkspace: (body: ImportWorkspaceRequest) => Promise<void>;
90	  clearImportError: () => void;
91	  removeLocalSummary: (workspaceId: string) => void;
92	  syncCurrentWorkspace: () => Promise<void>;
93	  clearSyncError: () => void;
94	
95	  activeSurface: WorkspaceSurface;
96	  openTaskTabs: TaskTabEntry[];
97	  activeTaskTabId: string | null;
98	  openTaskTab: (
99	    entry: Omit<TaskTabEntry, "sessionId" | "workspaceId">,
100	    options?: TabOpenOptions,
101	  ) => void;
102	  closeTaskTab: (sessionId: string) => void;
103	  activateTaskTab: (sessionId: string) => void;
104	  markTaskTabActive: (sessionId: string) => void;
105	  openFeatureTabs: FeatureTabEntry[];
106	  activeFeatureTabId: string | null;
107	  openFeatureTab: (
108	    entry: Omit<FeatureTabEntry, "sessionId" | "workspaceId">,
109	    options?: TabOpenOptions,
110	  ) => void;
111	  closeFeatureTab: (sessionId: string) => void;
112	  activateFeatureTab: (sessionId: string) => void;
113	  markFeatureTabActive: (sessionId: string) => void;
114	  goToBoard: () => void;
115	};
116	
117	export type WorkspaceActionsContextValue = Pick<
118	  WorkspaceContextValue,
119	  | "syncCurrentWorkspace"
120	  | "syncingWorkspace"
121	  | "syncError"
122	  | "openTaskTab"
123	  | "openFeatureTab"
124	>;
125	
126	const WorkspaceContext = createContext<WorkspaceContextValue | null>(null);
127	const WorkspaceActionsContext =
128	  createContext<WorkspaceActionsContextValue | null>(null);
129	
130	export function WorkspaceProvider({ children }: { children: ReactNode }) {
131	  const router = useRouter();
132	  const queryClient = useQueryClient();
133	  const [summaries, setSummaries] = useState<LocalWorkspaceSummary[]>(() =>
134	    getLocalWorkspaceSummaries(),
135	  );
136	  const [selectedWorkspaceId, setSelectedWorkspaceIdState] = useState<
137	    string | null
138	  >(() => getSelectedWorkspaceId());
139	  const [activeWorkspace, setActiveWorkspace] =
140	    useState<WorkspaceDetail | null>(null);
141	  const [loadingWorkspace, setLoadingWorkspace] = useState(() => {
142	    const storedSummaries = getLocalWorkspaceSummaries();
143	    const storedId = getSelectedWorkspaceId();
144	    return Boolean(resolveBootstrapWorkspaceId(storedSummaries, storedId));
145	  });
146	  const [workspaceError, setWorkspaceError] = useState<ApiError | null>(null);
147	  const [importingWorkspace, setImportingWorkspace] = useState(false);
148	  const [importError, setImportError] = useState<ApiError | null>(null);
149	  const [syncingWorkspace, setSyncingWorkspace] = useState(false);
150	  const [syncError, setSyncError] = useState<ApiError | null>(null);
151	
152	  const [activeSurface, setActiveSurface] = useState<WorkspaceSurface>("board");
153	  const [openTaskTabs, setOpenTaskTabs] = useState<TaskTabEntry[]>([]);
154	  const [activeTaskTabId, setActiveTaskTabId] = useState<string | null>(null);
155	  const [openFeatureTabs, setOpenFeatureTabs] = useState<FeatureTabEntry[]>([]);
156	  const [activeFeatureTabId, setActiveFeatureTabId] = useState<string | null>(
157	    null,
158	  );
159	  const openTaskTabsRef = useRef(openTaskTabs);
160	  const openFeatureTabsRef = useRef(openFeatureTabs);
161	  const loadWorkspaceSequenceRef = useRef(createRequestSequence());
162	  const didBootstrapRef = useRef(false);
163	
164	  useEffect(() => {
165	    openTaskTabsRef.current = openTaskTabs;
166	  }, [openTaskTabs]);
167	
168	  useEffect(() => {
169	    openFeatureTabsRef.current = openFeatureTabs;
170	  }, [openFeatureTabs]);
171	
172	  const isWorkspaceNotFound = useCallback((err: ApiError) => {
173	    return (
174	      err.code === "DATABASE_NOT_FOUND" ||
175	      err.code === "GITHUB_NOT_FOUND" ||
176	      err.code === "WORKSPACE_NOT_FOUND"
177	    );
178	  }, []);
179	
180	  const handleMissingWorkspace = useCallback(
181	    (workspaceId: string) => {
182	      removeLocalWorkspaceSummary(workspaceId);
183	      const updatedSummaries = getLocalWorkspaceSummaries();
184	      setSummaries(updatedSummaries);
185	
186	      if (selectedWorkspaceId === workspaceId) {
187	        clearSelectedWorkspaceId();
188	        setSelectedWorkspaceIdState(null);
189	      }
190	
191	      setActiveWorkspace(null);
192	      setWorkspaceError(null);
193	      setLoadingWorkspace(false);
194	      router.replace("/admin/connect");
195	    },
196	    [router, selectedWorkspaceId],
197	  );
198	
199	  const loadWorkspace = useCallback(
200	    (workspaceId: string) => {
201	      const requestId = loadWorkspaceSequenceRef.current.next();
202	      setLoadingWorkspace(true);
203	      setWorkspaceError(null);
204	      getWorkspace(workspaceId)
205	        .then((detail) => {
206	          if (!loadWorkspaceSequenceRef.current.isCurrent(requestId)) return;
207	          setActiveWorkspace(detail);
208	          setLoadingWorkspace(false);
209	        })
210	        .catch((err: ApiError) => {
211	          if (!loadWorkspaceSequenceRef.current.isCurrent(requestId)) return;
212	          if (isWorkspaceNotFound(err)) {
213	            handleMissingWorkspace(workspaceId);
214	            return;
215	          }
216	          setWorkspaceError(err);
217	          setLoadingWorkspace(false);
218	        });
219	    },
220	    [handleMissingWorkspace, isWorkspaceNotFound],
221	  );
222	
223	  useEffect(() => {
224	    if (didBootstrapRef.current) return;
225	    didBootstrapRef.current = true;
226	
227	    const storedSummaries = getLocalWorkspaceSummaries();
228	    const storedId = getSelectedWorkspaceId();
229	    setSummaries(storedSummaries);
230	
231	    const workspaceId = resolveBootstrapWorkspaceId(storedSummaries, storedId);
232	
233	    if (workspaceId) {
234	      setSelectedWorkspaceIdState(workspaceId);
235	      loadWorkspace(workspaceId);
236	    } else {
237	      setLoadingWorkspace(false);
238	    }
239	  }, [loadWorkspace]);
240	
241	  const selectWorkspace = useCallback(
242	    (workspaceId: string) => {
243	      setSelectedWorkspaceIdState(workspaceId);
244	      setSelectedWorkspaceId(workspaceId);
245	      setActiveWorkspace(null);
246	
247	      // Close all open tabs — stale tabs from the previous workspace
248	      // must not survive a workspace switch.
249	      setOpenTaskTabs([]);
250	      setOpenFeatureTabs([]);
251	      setActiveTaskTabId(null);
252	      setActiveFeatureTabId(null);
253	      setActiveSurface("board");
254	
255	      // Clear board-level persisted filter/mode state so the new
256	      // BoardProvider starts with factory defaults instead of stale
257	      // values from the previous workspace.
258	      clearStatusFilter();
259	      clearFeatureStatusFilter();
260	      clearBoardMode();
261	
262	      const summary = summaries.find((s) => s.workspaceId === workspaceId);
263	      if (summary) {
264	        const updated: LocalWorkspaceSummary = {
265	          ...summary,
266	          last_opened_at: new Date().toISOString(),
267	        };
268	        saveLocalWorkspaceSummary(updated);
269	        setSummaries(getLocalWorkspaceSummaries());
270	      }
271	
272	      loadWorkspace(workspaceId);
273	    },
274	    [summaries, loadWorkspace],
275	  );
276	
277	  const importWorkspaceFn = useCallback(
278	    async (body: ImportWorkspaceRequest) => {
279	      setImportingWorkspace(true);
280	      setImportError(null);
281	      try {
282	        const detail = await apiImportWorkspace(body);
283	
284	        const summary = buildImportLocalSummary(
285	          detail,
286	          body,
287	          new Date().toISOString(),
288	        );
289	        loadWorkspaceSequenceRef.current.next();
290	        saveLocalWorkspaceSummary(summary);
291	        setSelectedWorkspaceId(detail.id);
292	        setSummaries(getLocalWorkspaceSummaries());
293	        setSelectedWorkspaceIdState(detail.id);
294	        setActiveWorkspace(detail);
295	      } catch (err) {
296	        setImportError(err as ApiError);
297	        throw err;
298	      } finally {
299	        setImportingWorkspace(false);
300	      }
301	    },
302	    [],
303	  );
304	
305	  const clearImportError = useCallback(() => {
306	    setImportError(null);
307	  }, []);
308	
309	  const syncCurrentWorkspace = useCallback(async () => {
310	    if (!selectedWorkspaceId) return;
311	    setSyncingWorkspace(true);
312	    setSyncError(null);
313	    try {
314	      const detail = await apiSyncWorkspace(selectedWorkspaceId);
315	      setActiveWorkspace(detail);
316	      // Update board detail cache immediately with fresh sync data
317	      queryClient.setQueryData(workspaceKeys.detail(selectedWorkspaceId), detail);
318	      // Invalidate sidebar tasks so they refetch in the background
319	      queryClient.invalidateQueries({
320	        queryKey: ["workspace", selectedWorkspaceId, "sidebar-tasks"],
321	      });
322	    } catch (err) {
323	      const apiError = err as ApiError;
324	      if (isWorkspaceNotFound(apiError)) {
325	        handleMissingWorkspace(selectedWorkspaceId);
326	        return;
327	      }
328	      setSyncError(apiError);
329	      throw err;
330	    } finally {
331	      setSyncingWorkspace(false);
332	    }
333	  }, [handleMissingWorkspace, isWorkspaceNotFound, queryClient, selectedWorkspaceId]);
334	
335	  const clearSyncError = useCallback(() => {
336	    setSyncError(null);
337	  }, []);
338	
339	  const removeLocalSummary = useCallback(
340	    (workspaceId: string) => {
341	      removeLocalWorkspaceSummary(workspaceId);
342	      setSummaries(getLocalWorkspaceSummaries());
343	      if (selectedWorkspaceId === workspaceId) {
344	        const remaining = getLocalWorkspaceSummaries();
345	        const next = remaining[0] ?? null;
346	        if (next) {
347	          setSelectedWorkspaceIdState(next.workspaceId);
348	          setSelectedWorkspaceId(next.workspaceId);
349	          loadWorkspace(next.workspaceId);
350	        } else {
351	          setSelectedWorkspaceIdState(null);
352	          setActiveWorkspace(null);
353	        }
354	      }
355	    },
356	    [selectedWorkspaceId, loadWorkspace],
357	  );
358	
359	  const openTaskTab = useCallback(
360	    (
361	      entry: Omit<TaskTabEntry, "sessionId" | "workspaceId">,
362	      options?: TabOpenOptions,
363	    ) => {
364	      const workspaceId = selectedWorkspaceId ?? activeWorkspace?.id;
365	      if (!workspaceId) return;
366	      if (!options?.forceNewSession) {
367	        const existing = openTaskTabsRef.current.find(
368	          (tab) =>
369	            tab.taskId === entry.taskId && tab.workspaceId === workspaceId,
370	        );
371	        if (existing) {
372	          setActiveTaskTabId(existing.sessionId);
373	          setActiveSurface("task-tab");
374	          router.push(getTaskTabHref(existing));
375	          return;
376	        }
377	      }
378	      const tab: TaskTabEntry = {
379	        ...entry,
380	        workspaceId,
381	        sessionId: createTabSessionId("task"),
382	      };
383	      setOpenTaskTabs((prev) => addTaskTab(prev, tab));
384	      setActiveTaskTabId(tab.sessionId);
385	      setActiveSurface("task-tab");
386	      router.push(getTaskTabHref(tab));
387	    },
388	    [activeWorkspace?.id, router, selectedWorkspaceId],
389	  );
390	
391	  const closeTaskTab = useCallback(
392	    (sessionId: string) => {
393	      // Look up the tab being closed to check for parent feature tab context
394	      const tab = openTaskTabsRef.current.find(
395	        (t) => t.sessionId === sessionId,
396	      );
397	      setOpenTaskTabs((prev) => removeTaskTab(prev, sessionId));
398	      if (activeTaskTabId === sessionId) {
399	        setActiveTaskTabId(null);
400	        if (tab?.parentFeatureTabSessionId) {
401	          // Reactivate the parent feature tab instead of going to board
402	          const parentTab = openFeatureTabsRef.current.find(
403	            (ft) => ft.sessionId === tab.parentFeatureTabSessionId,
404	          );
405	          if (parentTab) {
406	            setActiveFeatureTabId(parentTab.sessionId);
407	            setActiveSurface("feature-tab");
408	            router.push(getFeatureTabHref(parentTab));
409	            return;
410	          }
411	        }
412	        setActiveSurface("board");
413	        router.push("/board");
414	      }
415	    },
416	    [activeTaskTabId, router],
417	  );
418	
419	  const activateTaskTab = useCallback(
420	    (sessionId: string) => {
421	      const tab = openTaskTabs.find((entry) => entry.sessionId === sessionId);
422	      if (!tab) return;
423	      setActiveTaskTabId(sessionId);
424	      setActiveSurface("task-tab");
425	      router.push(getTaskTabHref(tab));
426	    },
427	    [openTaskTabs, router],
428	  );
429	
430	  const markTaskTabActive = useCallback((sessionId: string) => {
431	    setActiveTaskTabId(sessionId);
432	    setActiveFeatureTabId(null);
433	    setActiveSurface("task-tab");
434	  }, []);
435	
436	  const openFeatureTab = useCallback(
437	    (
438	      entry: Omit<FeatureTabEntry, "sessionId" | "workspaceId">,
439	      options?: TabOpenOptions,
440	    ) => {
441	      const workspaceId = selectedWorkspaceId ?? activeWorkspace?.id;
442	      if (!workspaceId) return;
443	      if (!options?.forceNewSession) {
444	        const existing = openFeatureTabsRef.current.find(
445	          (tab) =>
446	            tab.featureId === entry.featureId &&
447	            tab.workspaceId === workspaceId,
448	        );
449	        if (existing) {
450	          setActiveFeatureTabId(existing.sessionId);
451	          setActiveSurface("feature-tab");
452	          router.push(getFeatureTabHref(existing));
453	          return;
454	        }
455	      }
456	      const tab: FeatureTabEntry = {
457	        ...entry,
458	        workspaceId,
459	        sessionId: createTabSessionId("feature"),
460	      };
461	      setOpenFeatureTabs((prev) => addFeatureTab(prev, tab));
462	      setActiveFeatureTabId(tab.sessionId);
463	      setActiveSurface("feature-tab");
464	      router.push(getFeatureTabHref(tab));
465	    },
466	    [activeWorkspace?.id, router, selectedWorkspaceId],
467	  );
468	
469	  const closeFeatureTab = useCallback(
470	    (sessionId: string) => {
471	      setOpenFeatureTabs((prev) => removeFeatureTab(prev, sessionId));
472	      if (activeFeatureTabId === sessionId) {
473	        setActiveFeatureTabId(null);
474	        setActiveSurface("board");
475	        router.push("/board");
476	      }
477	    },
478	    [activeFeatureTabId, router],
479	  );
480	
481	  const activateFeatureTab = useCallback(
482	    (sessionId: string) => {
483	      const tab = openFeatureTabs.find(
484	        (entry) => entry.sessionId === sessionId,
485	      );
486	      if (!tab) return;
487	      setActiveFeatureTabId(sessionId);
488	      setActiveSurface("feature-tab");
489	      router.push(getFeatureTabHref(tab));
490	    },
491	    [openFeatureTabs, router],
492	  );
493	
494	  const markFeatureTabActive = useCallback((sessionId: string) => {
495	    setActiveFeatureTabId(sessionId);
496	    setActiveTaskTabId(null);
497	    setActiveSurface("feature-tab");
498	  }, []);
499	
500	  const goToBoard = useCallback(() => {
501	    setActiveSurface("board");
502	    setActiveTaskTabId(null);
503	    setActiveFeatureTabId(null);
504	    router.push("/board");
505	  }, [router]);
506	
507	  const value = useMemo<WorkspaceContextValue>(
508	    () => ({
509	      summaries,
510	      selectedWorkspaceId,
511	      activeWorkspace,
512	      loadingWorkspace,
513	      workspaceError,
514	      importingWorkspace,
515	      importError,
516	      syncingWorkspace,
517	      syncError,
518	      selectWorkspace,
519	      importWorkspace: importWorkspaceFn,
520	      clearImportError,
521	      removeLocalSummary,
522	      syncCurrentWorkspace,
523	      clearSyncError,
524	      activeSurface,
525	      openTaskTabs,
526	      activeTaskTabId,
527	      openTaskTab,
528	      closeTaskTab,
529	      activateTaskTab,
530	      markTaskTabActive,
531	      openFeatureTabs,
532	      activeFeatureTabId,
533	      openFeatureTab,
534	      closeFeatureTab,
535	      activateFeatureTab,
536	      markFeatureTabActive,
537	      goToBoard,
538	    }),
539	    [
540	      summaries,
541	      selectedWorkspaceId,
542	      activeWorkspace,
543	      loadingWorkspace,
544	      workspaceError,
545	      importingWorkspace,
546	      importError,
547	      syncingWorkspace,
548	      syncError,
549	      selectWorkspace,
550	      importWorkspaceFn,
551	      clearImportError,
552	      removeLocalSummary,
553	      syncCurrentWorkspace,
554	      clearSyncError,
555	      activeSurface,
556	      openTaskTabs,
557	      activeTaskTabId,
558	      openTaskTab,
559	      closeTaskTab,
560	      activateTaskTab,
561	      markTaskTabActive,
562	      openFeatureTabs,
563	      activeFeatureTabId,
564	      openFeatureTab,
565	      closeFeatureTab,
566	      activateFeatureTab,
567	      markFeatureTabActive,
568	      goToBoard,
569	    ],
570	  );
571	
572	  const actionsValue = useMemo<WorkspaceActionsContextValue>(
573	    () => ({
574	      syncCurrentWorkspace,
575	      syncingWorkspace,
576	      syncError,
577	      openTaskTab,
578	      openFeatureTab,
579	    }),
580	    [
581	      syncCurrentWorkspace,
582	      syncingWorkspace,
583	      syncError,
584	      openTaskTab,
585	      openFeatureTab,
586	    ],
587	  );
588	
589	  return (
590	    <WorkspaceContext.Provider value={value}>
591	      <WorkspaceActionsContext.Provider value={actionsValue}>
592	        {children}
593	      </WorkspaceActionsContext.Provider>
594	    </WorkspaceContext.Provider>
595	  );
596	}
597	
598	export function useWorkspaceContext(): WorkspaceContextValue {
599	  const ctx = useContext(WorkspaceContext);
600	  if (!ctx) {
601	    throw new Error(
602	      "useWorkspaceContext must be used within a WorkspaceProvider",
603	    );
604	  }
605	  return ctx;
606	}
607	
608	export function useWorkspaceActionsContext(): WorkspaceActionsContextValue {
609	  const ctx = useContext(WorkspaceActionsContext);
610	  if (!ctx) {
611	    throw new Error(
612	      "useWorkspaceActionsContext must be used within a WorkspaceProvider",
613	    );
614	  }
615	  return ctx;
616	}
